sys_variable_value.value:
(function execute(inputs, outputs) {
   var fieldMapping = {
       "v_estoque_da_divida_publica_interna": "divida_publica_interna",
       "v_estoque_da_divida_publica_externa": "divida_publica_externa",
       "v_estoque_total_da_divida_publica_soma_interna_externa": "soma_interna_externa",
       "v_ano": "ano"
   };


   var grMultiRow = new GlideRecord('sc_multi_row_question_answer');
   grMultiRow.addEncodedQuery('row_index=' + inputs.row_index + '^parent_id=' + inputs.parent_id);
   grMultiRow.query();

   while (grMultiRow.next()) {
       var questionName = grMultiRow.item_option_new.name;
       var value = grMultiRow.getValue('value');

       if (fieldMapping[questionName]) {
           fieldMapping[questionName] = value;
       }
   }

outputs.ano = fieldMapping['v_ano'];
outputs.divida_publica_externa = fieldMapping['v_estoque_da_divida_publica_externa'];
outputs.divida_publica_interna = fieldMapping['v_estoque_da_divida_publica_interna'];
outputs.soma_interna_externa = fieldMapping['v_estoque_total_da_divida_publica_soma_interna_externa'];

})(inputs, outputs);

